 steps=[f"Read the task and identify the alphabet skill: {tag}.",f"Check the relevant evidence: letter order, sound, shape, position, spelling, or word use; the key rule is: {exp}",f"Check option {aid}: {ans}","Reject the alternatives by comparing each letter's identity and position rather than guessing from visual similarity or a single sound.","Reread the item, say the word or sequence aloud if useful, and verify that the chosen letters, order, spelling, and meaning agree."]
 return {"id":f"question-english-content-aa-{i}","subject":"english","type":"single-choice","prompt":prompt,"options":options,"knowledgeIds":["kg-english-content-aa"],"difficulty":"medium","answer":{"value":aid,"explanation":exp+f" Correct answer: {ans}"},"provenance":{"origin":"original","license":"All rights reserved","sourceUrl":SOURCES[0][0],"sourceLocator":"Public-school English assessment materials; this item studies assessment patterns only and does not reproduce an original question, option, image, or answer.","authoringNote":"Written independently from the official English curriculum KG and three public-school English assessment sources; alphabet prompts, options, explanations, and transfer task are original; pending second-round AI/Terra content review."},"reviewStatus":"draft","updatedAt":"2026-09-09","lessonId":"lesson-english-content-aa","examPatternRefs":refs,"solutionStrategy":"Identify the letter task first, then compare order, sound, shape, position, spelling, and word meaning; verify the selected form in the complete sequence or word.","solutionSteps":steps}
